import os,re
pat = re.compile(r'\[(Scheme\.)?HasPicSchemeEt |\[(Scheme\.)?HasPicScheme |\(rep : [^)]*RepresentableBy|\[(Scheme\.)?PicSharpRepresentable')
# count declaration headers whose signature (decl start to ":=" or ": ... :=") contains a gate binder
count=0; files={}
for root,_,fs in os.walk('AlgebraicJacobian'):
    for f in fs:
        if not f.endswith('.lean'): continue
        p=os.path.join(root,f)
        src=open(p).read()
        # split into declarations
        decls=re.split(r'\n(?=(?:private |protected |noncomputable |@\[[^\]]*\]\n)*(?:theorem|lemma|def|instance|abbrev|class|structure|example) )', src)
        for d in decls:
            head=d.split(':=')[0]
            if re.match(r'^(private |protected |noncomputable |@\[[^\]]*\]\n)*(theorem|lemma|def|instance|abbrev|class) ', d) and pat.search(head):
                count+=1; files[p]=files.get(p,0)+1
print('declarations binding a gate/rep hypothesis:',count)
for k,v in sorted(files.items(), key=lambda x:-x[1]): print(f'  {v:3d}  {k}')
